    static long solve(long h){
        if(h == 1){
            return 1;
        } else {
            return 1+solve(h/2)*2;
        }
    }

    static long solve2(long h){
        int bit = 0;
        while(h != 0){
            bit++;
            h >>= 1;
        }
        return (1L<<bit)-1;
    }


