class AtCoder {

    final int A, B, C, K;

    AtCoder(FastScanner sc) {
        A = sc.nextInt();
        B = sc.nextInt();
        C = sc.nextInt();
        K = sc.nextInt();
    }

    void solve(PrintWriter out) {
