		int B = S.charAt(1) - '0';
		int C = S.charAt(2) - '0';
		int D = S.charAt(3) - '0';

		String op1;
		String op2;
		String op3;
		for (int i = 0; i < (1 << 3); i++) {
			int sum = A;
			if (((i >> 0) & 1) == 0) {
				op1 = "+";
				sum += B;
			} else {
				op1 = "-";
				sum -= B;
			}

			if (((i >> 1) & 1) == 0) {
				op2 = "+";
				sum += C;
			} else {
				op2 = "-";
				sum -= C;
			}

			if (((i >> 2) & 1) == 0) {
				op3 = "+";
				sum += D;
			} else {
				op3 = "-";
				sum -= D;
			}

			if (sum == 7) {
				System.out.println(A + op1 + B + op2 + C + op3 + D + "=7");
				break;
			}
		}

	}
