class AtCoder {

    final int N;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
    }

    void solve(PrintWriter out) {
        int cnt = 0;
        for (int i = 1; i <= N; i++) {
            if (i % 2 != 0 && enumDiv(i).size() == 8) {
                cnt++;
            }
        }
        out.println(cnt);
    }

    List<Integer> enumDiv(int n) {
        List<Integer> list = new ArrayList<>();
        int sqrt = (int) Math.sqrt(n);
        for (int i = 1; i <= sqrt; i++) {
            if (n % i == 0) {
                list.add(i);
                if (i * i != n) {
                    list.add(n / i);
                }
            }
        }
        return list;
    }
}

