        solver.solve(in, out);
        out.close();
    }

    static class Task {

        void solve(InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int[] H = in.nextIntArray(N);

            int max = 0;
            int succ = 0;

            for (int i = 0; i < N - 1; ++i) {
                if (H[i] >= H[i + 1]) {
                    succ++;
                    max = Math.max(succ, max);
                } else {
                    succ = 0;
                }
            }

            out.println(max);
        }

    }

