class AtCoder {

    /* 変数宣言 */
    int N;
    long[] A;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        A = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLong();
        }
    }

    void solve(PrintWriter out) {
        final BigInteger MAX_VALUE = new BigInteger("1000000000000000000");
        BigInteger result = new BigInteger("1");
        Arrays.sort(A);

        if (A[0] == 0) {
            out.println(0);
        } else {
            for (int i = 0; i < N; i++) {
                BigInteger b1 = BigInteger.valueOf(A[i]);
                if (result.compareTo(MAX_VALUE) == 1) {
                    out.println(-1);
                    return;
                } else {
                    result = result.multiply(b1);
                }
            }
            if (result.compareTo(MAX_VALUE) == 1) {
                out.println(-1);
                return;
            }
            out.println(result);
        }
    }
}

