            stack.add(in.next());
            for(int i = 1; i<n; i++){
                String str = in.next();
                if(stack.contains(str)){
                    flag = false;
                    break;
                }
                if(stack.peek().charAt(stack.peek().length()-1) != str.charAt(0)){
                    flag = false;
                    break;
                }
                else stack.add(str);
            }
            if(flag) System.out.println("Yes");
