    static class BKThCommonDivisor {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int a = in.nextInt(), b = in.nextInt();
            int k = in.nextInt();

            int answer = -1;
            for (int i = NumberTheory.gcd(a, b); i >= 1; i--) {
                if (a % i == 0 && b % i == 0) {
                    k--;
                }
                if (k == 0) {
                    answer = i;
                    break;
                }
            }

            out.println(answer);
        }

    }

