    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String S = in.readString();
            Set<Character> acgt = new HashSet<>();
            acgt.add('A');
            acgt.add('C');
            acgt.add('G');
            acgt.add('T');
            int maxLength = 0;
            int tmpLength;
            for (int i = 0; i < S.length(); i++) {
                tmpLength = 0;
                for (int j = i; j < S.length(); j++) {
