class Solver {
	Scanner sc;
	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ======================================================================
    public void solve() {
    	String S = ns();
    	String T = ns();
    	int A = ni();
    	int B = ni();
    	String U = ns();
    	if(U.equals(S))			out.println((A-1) + " " + B);
    	else if(U.equals(T))	out.println(A + " " + (B-1));
    	else					out.println(A + " " + B);
    }
