		solve(sc,out);

		out.flush();
	}

	public static void solve(FastScanner sc, PrintWriter out) {
		int n = sc.nextInt();
		int y = sc.nextInt();

		for(int i = 0; i <= n; i++) {
			for(int j = 0; j <= n-i; j++) {
				int k = n-i-j;

				if(i*10000+j*5000+k*1000 == y) {
					out.println(i + " " + j + " " + k);
					return;
				}
			}
		}
		out.println("-1 -1 -1");
	}

	public static int gcd(int a, int b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}

	public static long gcd(long a, long b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}

	public static int lcm(int a, int b) {
		return (a * b) / gcd(a, b);
	}
}

