class InputReader {

	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;
	private SpaceCharFilter filter;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	public int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}

	public int readInt() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		int res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

	public String readString() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
			c = read();
		} while (!isSpaceChar(c));
		return res.toString();
	}

	public long readLong() {
		int c = read();
		while (isSpaceChar(c)) {
			c = read();
		}
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		long res = 0;
		do {
			if (c < '0' || c > '9') {
				throw new InputMismatchException();
			}
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

	public boolean isSpaceChar(int c) {
		if (filter != null)
			return filter.isSpaceChar(c);
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}

	public String next() {
		return readString();
	}

	public interface SpaceCharFilter {
		public boolean isSpaceChar(int ch);
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String args[]) {

		Scanner sc = new Scanner(System.in);
		String s = sc.nextLine();
		int[] num = new int[4];

		num[0] = Integer.parseInt(s.substring(0, 1));
		num[1] = Integer.parseInt(s.substring(1, 2));
		num[2] = Integer.parseInt(s.substring(2, 3));
		num[3] = Integer.parseInt(s.substring(3, 4));

		String ans = calc(num, 0, "+", 0);
		if (ans.length() < 4) {
			System.out.println("");
		} else {
			String a = String.valueOf(num[0]);
			for (int i = 1; i <= 3; i++) {
				a = a + String.valueOf(ans.charAt(i));
				a = a + String.valueOf(num[i]);
			}
			a = a + "=7";
			System.out.println(a);
		}
	}

	public static String calc(int[] num, int numind, String op, int sum) {
		int n = num[numind];
		if (op.equals("-"))
			n *= -1;

		int newsum = sum + n;
		if (numind >= 3) {
			if (newsum == 7) {
				return op;
			} else {
				return "";
			}
		} else {
			String s = calc(num, numind + 1, "+", newsum);
			if (s.length() > 0) {
				return op + s;
			} else {
				s = calc(num, numind + 1, "-", newsum);
				if (s.length() > 0)
					return op + s;
				return s;
			}
		}
	}
}

