						if (c == '.') 
						{ 
							while ((c = read()) >= '0' && c <= '9') 
							{ 
								ret += (c - '0') / (div *= 10); 
							} 
						} 

						if (neg) 
							return -ret; 
						return ret; 
					} 

					private void fillBuffer() throws IOException 
					{ 
