					ans=c*2*x;
				}else {
				ans=a*(x-y)+c*2*y;
				}
			}else {
				if(b>2*c) {
					ans=c*2*y;
				}else {
					ans=b*(y-x)+c*2*x;
				}
			}
		}

		PrintWriter out = new PrintWriter(System.out);
