class AtCoder {

    /* 変数宣言 */
    final int A, B;

    AtCoder(FastScanner sc) {
        A = sc.nextInt();
        B = sc.nextInt();
    }

    void solve(PrintWriter out) {
        out.println(lcm(A, B));
    }

    long gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }

    /*  lcm (a, b) : 2整数版
        入力：整数 a, b
        出力：aとbの最小公倍数
    */
    long lcm(int a, int b) {
        long d = gcd(a, b);
        return a / d * b;
    }

    boolean isPrimeNumber(int num) {
        for (int i = 2; i < num; i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

