public class Main {
  private static int s(int n) {
    int sum = 0;
    while (n > 0) {
      sum += n % 10;
      n /= 10;
    }
    return sum;
  }

  private static boolean solve(int n) {
    return n % s(n) == 0;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
