			// System.out.println("val: " + val);
			if (maxHeap.size() < k) {
				maxHeap.offer(val);
			} else {
				if (val < maxHeap.peek()) {
					maxHeap.poll();
					maxHeap.offer(val);
				}
			}
		}

		int ans = 0;
		while (!maxHeap.isEmpty()) {
			ans += maxHeap.poll();
		}
		System.out.println(ans);
	}

}



