    static public void main(String args[]) {
        long a = sc.nextLong();
        long b = sc.nextLong();
        System.out.println(lcm(a, b));
    }

    static long lcm (long a, long b) {
        long temp;
        long c = a * b;
        if (a < b) {
            temp = a;
            a = b;
            b = temp;
        }
        while ((temp = a % b) != 0) {
            a = b;
            b = temp;
        }
        return c / b;
    }
