        int temp=0;
        for(int i=0;i<num.length-1;i++){
            for(int j=num.length-1;j>i;j--){
                if(num[j] > num[j-1]){
                    temp=num[j];
                    num[j]=num[j-1];
                    num[j-1]=temp;
                }
            }
        }
        return num;
    }
}

