class Main {
	static class GreatestCommonDivisor {
		public void greatestcommondivisor (InputReader ir) {

			//２つの自然数入力
			int x = ir.nextInt();
			int y = ir.nextInt();

			StringBuilder sb = new StringBuilder ();		

			if ( x == y) sb.append(x); 
			else if (x > y) {
				int n = x % y;
				sb.append(Gcd(y,n));
			} else {
				int n = y % x;
				sb.append(Gcd(x,n));
			}

			System.out.println(sb);
		}

		//最大公約数を求める
		static int Gcd(int x, int y) {

			int n = Math.min(x, y);

			for (int i = n; i >= 1; i--) 
				if (x % i == 0 && y % i == 0) return i;

			return 1;
		}

	}

