		for (int i = 1; i <= N; i++) {
			if (i >= 5 && (equal(i-5,"dream")||equal(i-5,"erase"))) {
				dp[i] |= dp[i-5];
			}
			if (i >= 6 && equal(i-6,"eraser")) {
				dp[i] |= dp[i-6];
			}
			if (i >= 7 && equal(i-7,"dreamer")) {
				dp[i] |= dp[i-7];
			}
		}
		if (dp[N]) {
			pw.println("YES");
		} else {
			pw.println("NO");
		}
		pw.close();
	}

	public static boolean equal(int L, String com) {
		boolean ans = true;
		for (int i = 0; i < com.length(); i++) {
			if (com.charAt(i) != s[i+L]) {
				ans = false;
				break;
			}
		}
		return ans;
	}

	public static long dist(long[] p1, long[] p2) {
		return (Math.abs(p2[0]-p1[0])+Math.abs(p2[1]-p1[1]));
	}

	//Find the GCD of two numbers
	public static long gcd(long a, long b) {
		if (a < b) return gcd(b,a);
		if (b == 0)
			return a;
		else
			return gcd(b,a%b);
	}

	//Fast exponentiation (x^y mod m)
	public static long power(long x, long y, long m) { 
		if (y < 0) return 0L;
		long ans = 1;
		x %= m;
		while (y > 0) { 
			if(y % 2 == 1) 
				ans = (ans * x) % m; 
			y /= 2;  
			x = (x * x) % m;
		} 
		return ans; 
	}

