    int calcTime(int A, int B, int C, int D) {
        // C <-> DがA <-> Bの範囲と重複しない場合
        if (B <= C || D <= A) {
            return 0;
        }

        // CがAより小さい場合
        if (C < A) {
            // DがB以下なら，A<->Dが重複範囲となる
            if (D <= B) {
                return D - A;
            }
            // DがBより大きければ，A<->Bが重複範囲となる
            else {
                return B - A;
            }
        }
        // 残るケースはCがAとBの間にある場合のみ
        else {
            // DがB以下なら，C<->Dが重複範囲となる
            if (D <= B) {
                return D - C;
            }
            // DがBより大きければ，C<->Bが重複範囲となる
            else {
                return B - C;
            }

        }

    }

