class AtCoder {

    final int N, K;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        K = sc.nextInt();
    }

    void solve(PrintWriter out) {
        double prob = 0;
        for (int i = 1; i <= N; i++) {
            long point = i;
            int cnt = 0;
            while (point < K) {
                point *= 2;
                cnt++;
            }
            prob += 1.0 / N * Math.pow(0.5, cnt);
        }
        out.println(prob);
    }

}

