class Queue{

	private Process[] table;
	private int head;
	private int tail;
	private int size;
	private int num_data;

	Queue(int arg_size){

		size = arg_size;
		table = new Process[arg_size];
		head = 0;
		tail = 0;
		num_data = 0;
	}

	boolean isEmpty(){

		return num_data == 0;
	}

	void push(Process process){

		table[tail] = process;
		tail = (tail+1)%size;
		num_data++;
	}

	public Process pop(){

		head = (head+1)%size;
		num_data--;
		return table[(head-1+size)%size];
	}
}

