    static class solution {
        public void solve(int tc, InputReader sc, PrintWriter w) {
            int n = sc.nextInt();
            int a[] = new int[n + 1];
            for(int i = 0 ; i < n - 1 ; i++)
                a[sc.nextInt()]++;
            for(int i = 1 ; i <= n ; i++){
                w.println(a[i]);
            }
        }
