		long E = C*D;
		long F = Math.max(C,D);
		long G = Math.min(C,D);
		for( long i=1; i*i<=G; i++ ){
			if( G%i==0 ){
				if( F%(G/i)==0 ){
					E = (C*D)/(G/i);
					break;
				}
				if( F%i==0 ){
					E = (C*D)/i;
				}
			}
		}    
