class InputData {

	private List<Integer> numberList = new ArrayList<>();

	public InputData(BufferedReader br) throws IOException {
		String line;
		while((line = br.readLine()) != null) {
			this.numberList.add(Integer.valueOf(line.trim()));
		}
	}

