		int[] A = new int[N];
		for(int i=0; i<N; i++){
			A[i] = sc.nextInt();
		}

		int swap = 0;
		for(int i=0; i<N; i++){
			int idx_min = i;
			for(int j=i; j<N; j++){
				if(A[j] < A[idx_min]){
					idx_min = j;
				}
			}

			if(idx_min != i){
				int temp = A[i];
				A[i] = A[idx_min];
				A[idx_min] = temp;
				swap++;
			}
		}

		for(int i=0; i<N; i++){
			System.out.print(A[i]);
			if(i != N-1){
				System.out.print(" ");
			}
		}
