        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            int k = in.nextInt();
            Queue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
            for (int i = 0; i < n; i++) {
                heap.add(in.nextLong());
            }
            if (k >= n){
                out.println(0);
                return;
            }
            for (int i = 0; i < k; i++) {
                heap.remove();
            }
            long ans = 0;
            while (!heap.isEmpty()){
                ans += heap.remove();
            }
            out.println(ans);
        }
    }

