			int sum;
			int ans=0;
			for(int i=0;i<N;i++) {
				for(int b=i+1;b<N;b++) {

					sum=0;
					for(int a=0;a<D;a++) {
						sum+=(v[i][a]-v[b][a])*(v[i][a]-v[b][a]);
					}

					for(int t=1;t<=sum;t++) {
						if(t*t==sum) {
							ans++;
							break;
						}else if(t*t>sum)break;
					}
					//p(i+"    "+b+"   "+sum);

				}
			}p(ans);
	}


