    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
            }
            int[] right = new int[n];
            int[] left = new int[n];
            right[n-1] = 0;
            left[0] = 0;
            for (int i = n-2; i >= 0; i--) {
                right[i] = Math.max(arr[i+1], right[i+1]);
            }
            for (int i = 1; i < n; i++) {
                left[i] = Math.max(arr[i-1], left[i-1]);
            }
            for (int i = 0; i < n; i++) {
                out.println(Math.max(right[i], left[i]));
            }
        }
    }

