    static class AFrog1Editorial {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int h[] = new int[n + 1];
            for (int i = 1; i <= n; i++)
                h[i] = in.nextInt();
            int dp[] = new int[n + 1];
            dp[2] = Math.abs(h[2] - h[1]);
            for (int i = 3; i <= n; i++) {
                int v1 = dp[i - 1] + Math.abs(h[i] - h[i - 1]);
                int v2 = dp[i - 2] + Math.abs(h[i] - h[i - 2]);
                dp[i] = Math.min(v1, v2);
            }
            out.println(dp[n]);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

