    static class CAntiDivision {
        public void solve(int testNumber, LightScanner2 in, LightWriter2 out) {
            long a = in.longs(), b = in.longs(), c = in.longs(), d = in.longs();
            out.ans(solve(b, c, d) - solve(a - 1, c, d)).ln();
        }

        private static long solve(long x, long c, long d) {
            long ans = x;
            ans -= x / c;
            ans -= x / d;
            ans += x / IntMath.lcm(c, d);
            return ans;
        }

    }

    static abstract class LightScannerAdapter implements AutoCloseable {
        public abstract void close();

    }

    static final class IntMath {
        private IntMath() {
        }

        public static long lcm(long a, long b) {
            return a / gcd(a, b) * b;
        }

        public static long gcd(long a, long b) {
            long t;
            if (a == 0) return b;
            if (b == 0) return a;
            while (a % b > 0) {
                t = b;
                b = a % b;
                a = t;
            }
            return b;
        }

    }

