            number[i] = i+1;
        }

        for (int i = 0; i < num; i++) {
            for (int j = i+1; j < num; j++) {
                for (int k = j+1; k < num; k++) {
                    ans = (number[i] + number[j] + number[k]);
                    if (ans == sum) count++;
                }
            }
        }
        return count;
    }

