class Pair { 
   int x; 
   int y; 
   // Constructor 
   public Pair(int x, int y) 
   { 
       this.x = x; 
       this.y = y; 
   } 
	@Override
	public boolean equals(Object o) {
	    if (this == o) return true;
	    if (!(o instanceof Pair)) return false;
	    Pair p = (Pair) o;
	    return x == p.x && y == p.y;
	}	
	@Override
	public int hashCode() {
		return (""+x+"-"+y).hashCode();
	}	
}

