        }
        calc(n,m);
    }

    public static int calc(int n,long m){
        int x,y;
        boolean flg=true;
        m = m / 1000;
        if(m > 20000){
            System.out.println("-1 -1 -1");
            return 0;
        } else{
            int z1 = (int)m % 5;
            n -= z1;
            m = m - z1;
            for (x = 0;x <= n;x++){
                for(y = 0;y <= n-x;y++){
                    if((10 * x + 5 * y + (n - x - y)) == m){
                        System.out.println(x + " " + y + " " + (n-x-y+z1));
                        flg = false;
                        return 0;
                    }
                }
            }
            if(flg){
            System.out.println("-1 -1 -1");
            }
            return 0;
        }
