                for(int l=1;l<=k;l++){
                    ans+=helper(i,j,l);
                }
            }
        }
        System.out.println(ans);
    }

    private static long helper(int i, int j, int k) {

        long temp=gcd(i,j);
        long ans=gcd(temp,k);
        return ans;
    }

