            del[r]--;
        }
        int[] res = new int[n];
        res[0] = del[0];
        for (int i=1; i<n; i++) {
            res[i] = res[i - 1] + del[i];
        }
        int c = 0;
        for (int i=0; i<n; i++) {
            if (res[i] == m) {
