    static class Solve {
    	public static long gcf(long a, long b){
    	    while (a != b) {
    	        if (a > b) a -= b; 
    	        else b -= a;
    	    }
    	    return a;
    	}

    	public static long lcm(long a, long b){
    	    return (a * b) / gcf(a, b);
    	}
    	public void solve(int testNumber, InputReader in, OutputWriter out) {
    		out.println((long)lcm(in.nextLong(),in.nextLong()));
    	}
    }

