public class Main {

	public static void main(String[] args) throws IOException {
		ContestScanner scan = new ContestScanner();

		int n = scan.nextInt();

		int[] R = new int[n];

		for(int i=0; i < n; i++)
		{
			R[i] = scan.nextInt();
		}

		(new Solve(n, R)).solve();
