        for (int i = n - 1; i >= 0; i--) {
            if (isAliceTurn) {
                ans += list.get(i);
                isAliceTurn = !isAliceTurn;
            } else {
                ans -= list.get(i);
                isAliceTurn = !isAliceTurn;
            }
