		Deque<Integer> stack = new ArrayDeque<>();
		for(String op : s){
			if(isNumber(op)){
				stack.addLast(Integer.parseInt(op));
			}else{
				int b = stack.removeLast();
				int a = stack.removeLast();
				int c = 0;
				if(op.equals("+")){
					c = a + b;
				}else if(op.equals("-")){
					c = a - b;
				}else if(op.equals("*")){
					c = a * b;
				}
				stack.addLast(c);
			}	
		}
		System.out.println(stack.removeLast());
	}
