        for(int i = 0; i < N; i++ ) {
            int val =  in.nextInt();
            for(int k = 0; k < range.length; k++) {
                if(val <= range[k]){
                    cnt[k]++;
                    break;
                }
            }
        }

        int fixedColoredCnt = 0;
        for(int i = 0; i < range.length - 1; i++){
            if(cnt[i] > 0){
                fixedColoredCnt ++;
