  static class Solution {
    void solve() throws IOException {
      int x = in.nextInt();
      int y = in.nextInt();

      int gcd = gcd(x ,y);
      out.println(gcd);
//      End solve()
    }

    int gcd(int x, int y) {
      if (x < y) {
        int tmp = x;
        x = y;
        y= tmp;
      }
      while (y > 0) {
        int r = x % y;
        x = y;
        y = r;    
      }

      return x;
    }

//    End Solution
}


