	static int hz_swap(int a, int b){
		if(a >= b) return a;
		else return b;
	}

	static long hz_swap(long a, long b){
		if(a >= b) return a;
		else return b;
	}

	//mod上での差分
	static long hz_modSub(long a, long b, long mod){
		long v = a - b;
		if(v < 0) v += mod;
		return v % mod;
	}

	//mod上での割算
	static long hz_modDiv(long a, long b, long mod){
		return (a % mod) * hz_modInv(b, mod) % mod;
	}

	//逆元
	static long hz_modInv(long a, long mod){
		return hz_modPow(a, mod-2L, mod);
	}

	//mod上での累乗
	static long hz_modPow(long n, long k, long mod) {

		long result = 1L;

		// k を右シフトしつつ n を 2 乗していく
		while (k > 0L) {
			// k の最下ビットが 1 なら、今の n を答えに掛ける
			if ((k & 1L) == 1L)
				result = (result * n) % mod;
			n = n * n % mod;
			k >>= 1L;
		}

		return result;
	}

	//Union Find Tree
	static class HZ_UF{

		public int[] par;
		public int[] rank;

		public HZ_UF(int n){
			this.par = new int[n + 1];
			this.rank = new int[n + 1];

			Arrays.fill(par, -1);
			Arrays.fill(rank, 0);
		}

		public void unite(int x, int y){
			link(root(x), root(y));
		}

		public boolean link(int x, int y){
			if(x == y) return false;
			if(rank[x] > rank[y]){
				par[x] += par[y];
				par[y] = x;
			}
			else{
				par[y] += par[x];
				par[x] = y;
				if(rank[x] == rank[y]) rank[y]++;
			}
			return true;
		}

		public boolean isSame(int x, int y){
			return root(x) == root(y);
		}

		public int root(int x){
			if(par[x] < 0)	return x;
			else	return x = root(par[x]);
		}

		public int size(int x){
			return -par[root(x)];
		}
	}


