        for (int i = 0; i < s.length; i += 2) {
            if (s[i] == 'L') {
                return false;
            }
        }
        return true;
    }

    private static boolean cond2(final char[] s) {
        for (int i = 1; i < s.length; i += 2) {
            if (s[i] == 'R') {
                return false;
            }
        }
        return true;
    }
}

