/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BPowerSocket solver = new BPowerSocket();
        solver.solve(1, in, out);
        out.close();
    }

    static class BPowerSocket {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            int n = s.nextInt();
            int m = s.nextInt();
            int total = 1;
            int count = 0;
            while (total < m) {
                total -= 1;
                total += n;
                count++;
            }
            out.println(count);
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int peopleNum = scanner.nextInt();
        int[] array = new int[peopleNum];
        for (int i = 0; i < peopleNum; i++) {
            int rate = scanner.nextInt();
            array[i] = judgeColor(rate);
        }
        Arrays.sort(array);
        ArrayList<Integer> newArray = new ArrayList<Integer>();

        for (int j = 0; j < array.length-1; j++) {
            if (array[j] != array[j+1]) {
                newArray.add(array[j]);
            } else if (array[j] == 9 && array[j+1] == 9) {
                newArray.add(array[j]);
            }
        }
        newArray.add(array[array.length-1]);

        int freeColorCnt = 0;
        for (int k = 0; k < newArray.size(); k++) {
            if (newArray.get(k) == 9) {
                freeColorCnt++;
            }
        }

        int minColorCnt = newArray.size() - freeColorCnt;
        int maxColorCnt = minColorCnt + freeColorCnt;

        if(newArray.size() == freeColorCnt) {
            minColorCnt = 1;
            maxColorCnt = freeColorCnt;
        }
        System.out.println(minColorCnt + " " + maxColorCnt);
    }
    public static int judgeColor(int rate) {
        if(rate >= 1 && rate <= 399) {
            return 1;
        } else if (rate >= 400 && rate <= 799) {
            return 2;
        } else if (rate >= 800 && rate <= 1199) {
            return 3;
        } else if (rate >= 1200 && rate <= 1599) {
            return 4;
        } else if (rate >= 1600 && rate <= 1999) {
            return 5;
        } else if (rate >= 2000 && rate <= 2399) {
            return 6;
        } else if (rate >= 2400 && rate <= 2799) {
            return 7;
        } else if (rate >= 2800 && rate <= 3199) {
            return 8;
        } else {
            return 9;
        }
    }
}

