        }

        System.out.println(gcd(num[0],num[1]));
    }

    public static int gcd(int x, int y){
        int r;
        if(x < y){
            int tmp = x;
            x = y;
            y = tmp;
        }
        while(y > 0){
            r = x % y;
            x = y;
            y = r;
        }
        return x;
    }
}

