    static class Task {
        int L, R;

        void solve(InputReader in, PrintWriter out) {
            L = in.nextInt();
            R = in.nextInt();
            if (R - L + 1 >= 2019) {
                out.println(0);
            } else {
                int ans = Integer.MAX_VALUE;
                for (int i = L; i <= R; ++i) {
                    for (int j = i + 1; j <= R; ++j) {
                        ans = Math.min(ans, ((i % 2019)*(j % 2019)) % 2019);
                    }
                }
                out.println(ans);
            }
        }
    }

