import java.io.*;
import java.util.*;

public class Main {
  private static int solve(int n, int m, List<List<Integer>> am) {
    int[] counters = new int[m + 1];
    for (List<Integer> as : am) {
      for (int a : as) {
        counters[a]++;
      }
    }
    int count = 0;
    for (int c : counters) {
      if (c == n) {
        count++;
      }
    }
    return count;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    List<List<Integer>> am = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      List<Integer> as = new ArrayList<>();
      int k = reader.nextInt();
      for (int a : reader.nextIntArray(k)) {
        as.add(a);
      }
      am.add(as);
    }
    out.println(solve(n, m, am));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
