            double diff = Math.abs(kakudo - kakudoShort);

            double ans = Math.pow(longDistance, 2) +
                    Math.pow(shortDistance, 2) -
                    (2 * longDistance * shortDistance * Math.cos(Math.toRadians(diff)));

            out.append(String.valueOf(Math.sqrt(ans)));

        }

    }
}

