    public static long calc(long A, long B, long X) {
	long A_count = (A - 1) / X;
	long B_count = B / X;

	return B - A + 1 - (B_count - A_count);
    }

    public static long lcm(long a, long b) {
	long temp;
	long c = a;
	c *= b;
	while((temp = a % b) != 0) {
		a = b;
		b = temp;
	}

	return (long)(c / b);
    }

