    void solve() {
        Map<String, Integer> map = new HashMap<String, Integer>();
        for (char c = 'a'; c <= 'z'; c++) {
            map.put(String.valueOf(c), 0);
        }
        String str;
        while (sc.hasNext()) {
            str = sc.nextLine();
            char[] strArr = str.toCharArray();
            for (int i = 0; i < strArr.length; ++i) {
                if (map.containsKey(String.valueOf(Character.toLowerCase(strArr[i]))))
