public class Main {

	public static void main(String[] args) {
		FastScanner sc = new FastScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		solve(sc,out);

		out.flush();
	}

	public static void solve(FastScanner sc, PrintWriter out) {
		int n = sc.nextInt();
		int m = sc.nextInt();

		int[] l = new int[m];
		int[] r = new int[m];

		for(int i = 0; i < m; i++){
			l[i] = sc.nextInt();
			r[i] = sc.nextInt();
		}

		Arrays.sort(l);
		Arrays.sort(r);

		int res = 0;

		for(int i = 1; i <= n; i++) {
			if(l[l.length-1] <= i && i <= r[0]) {
				res++;
			}
		}

		out.println(res);

 	}

	public static int gcd(int a, int b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}

	public static long gcd(long a, long b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}
}

