public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int D = fs.nextInt();
        int[][] matrix = new int[N][D];

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < D; ++j) {
                matrix[i][j] = fs.nextInt();
            }
        }

        int ans = 0;
        for (int i = 0; i < N-1; ++i) {
            for (int j = i+1; j < N; ++j) {
                int tmp = 0;
                for (int k = 0; k < D; ++k) {
                    tmp += (matrix[i][k] - matrix[j][k]) * (matrix[i][k] - matrix[j][k]);
                }
                for (int k = 1; k <= Math.sqrt(tmp); ++k) {
//                    System.out.println(tmp);
                    if (k * k == tmp) {
                        ++ans;
                        break;
                    }
                }
            }
        }

        System.out.println(ans);
    }
}

