    private static void solve(FastScanner in, PrintWriter out){
        int n = in.nextInt();
        int w[] = new int[n];
        int sum = 0;
        for(int i=0;i<n;i++){
            w[i] = in.nextInt();
            sum+=w[i];
        }
        int w1[] = new int[n];
        int w2[] = new int[n];
        w1[0] = w[0];
        sum-=w[0];
        w2[0] = sum;
        for(int i=1;i<n;i++){
            w1[i] = w1[i-1]+w[i];
            sum-=w[i];
            w2[i] = sum;
        }
        int ans = 1000000000;
        for(int i=0;i<n;i++){
            int d = Math.abs(w1[i] - w2[i]);
            ans = Math.min(d,ans);
        }
        out.println(ans);
