public class Main {
  private static int solve(int n, int[][] am) {
    int answer = 0;
    for (int i = 0; i < n; i++) {
      int sum = 0;
      for (int j = 0; j <= i; j++) {
        sum += am[0][j];
      }
      for (int j = i; j < n; j++) {
        sum += am[1][j];
      }
      answer = Math.max(answer, sum);
    }
    return answer;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[][] am = reader.nextInt(2, n);
    out.println(solve(n, am));
  }

