class AtCoder {

    /* 変数宣言 */
    final int N;
    final int K;
    final int[] H;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        K = sc.nextInt();
        H = new int[N];
        for (int i = 0; i < N; i++) {
            H[i] = sc.nextInt();
        }

    }

    void solve(PrintWriter out) {
        long count=0;
        int MP = K;
        Arrays.sort(H);
        for (int i = H.length - 1; i >= 0; i--) {
            if (MP > 0) {
                MP--;
            } else {
                count += H[i];
            }
        }
        out.println(count);
    }
}

