    private void calcFact(int N) {
        fact = new long[N];
        invfact = new long[N];

        fact[0] = 1;
        for (int i = 1; i < N; i++)
            fact[i] = fact[i - 1] * i % M;

        invfact[0] = 1;
        for (int i = 1; i < N; i++) {
            long p = pow(i, M - 2);
            invfact[i] = invfact[i - 1] * p % M;
