        for (int i = 0; i < 4; i++) {
            a[i] = Character.getNumericValue(s.charAt(i));
        }

        for (int bit = 0; bit < (1 << 3); bit++) {
            int tmp = a[0];
            for (int i = 0; i < 3; i++) {
                if ((bit >> i & 1) == 1) {
                    tmp += a[i + 1];
                } else {
                    tmp -= a[i + 1];
                }
            }
            if (tmp == 7) {
                System.out.print(a[0]);
                for (int k = 0; k < 3; k++) {
                    if ((bit >> k & 1) == 1) {
                        System.out.print("+");
                    } else {
                        System.out.print("-");
                    }
                    System.out.print(a[k + 1]);
                }
                System.out.println("=7");
                return;
            }
        }
    }

