import java.io.*;
import java.sql.PreparedStatement;
import java.util.*;

public class Main {
    private static class Task {
        public void solve(InputReader in, PrintWriter out) {
            long n = in.nextInt();
            long a = n        * (n + 1)           / 2;
            long b = (n / 3)  * (n - n % 3  + 3)  / 2;
            long c = (n / 5)  * (n - n % 5  + 5)  / 2;
            long d = (n / 15) * (n - n % 15 + 15) / 2;
            out.println(a - b - c + d);
        }
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str;
            try {
                str = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }

    public static void main(String[] args) throws IOException {
        InputStream inputStream = new File("in.txt").exists() ? new FileInputStream("in.txt") : System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);
        out.close();
    }
}

import java.util.*;
import java.util.ArrayList;
import java.util.Collections;

public class Main{

  public static void main(String[] args){

    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();

    if(N == 1){
      int count1 = 0;
      int K1 = sc.nextInt();
      for(int i = 0; i < K1 ; i++){
        int love = sc.nextInt();
        if(love <= M){
          count1++;
        }
      }

      System.out.println(count1);

    }else{

    ArrayList<Integer> love = new ArrayList<Integer>();
    for(int i = 0; i < N ; i++){
      int K = sc.nextInt();
      int[] list = new int[K];
       for(int j = 0; j < K ; j++){
         list[j] = sc.nextInt();
         love.add(list[j]);
       }   
    }

    Collections.sort(love);

    ArrayList<Integer> countAll = new ArrayList<Integer>();
    int count = 0;
    for(int i = 1; i <= M  ; i++){
      for(int j = 0; j < love.size(); j++){
        int jd = love.get(j);
        if(jd == i){
          count = count + 1;
        }
      }
      countAll.add(count);
      count = 0;
    }

    int lastCount = 0;
    for(int i = 0; i < countAll.size() ; i++){
      if(countAll.get(i) == N){
        lastCount++;
      }
    }
    System.out.println(lastCount);   
    }
  }  
}

