				break;
			case "-":
				s.push(-1 * s.pop() + s.pop());
				break;
			case "*":
				s.push(s.pop() * s.pop());
				break;
			default:
				s.push(Integer.parseInt(str));
			}
		}

		System.out.println(s.pop());
	}

}

