    final static int MOD = (int)1e9+7;

    void solve(){
        long N = in.nextLong();

        int len = -1;
        long sum = 0, total = -1;
        for(int i = 1; i <= 20; i++){
            total = (long)Math.pow(26, i);
            sum += total;
            if(N <= sum){
                len = i;
                N -= sum - total;
                break;
            }
        }

        StringBuilder ans = new StringBuilder();
        for(int i = 1; i <= len; i++){
            total = (long)Math.pow(26, len - i);
            for(int j = 1; j <= 26; j++){
                if(N <= total * j){
                    N -= total * (j - 1);
                    ans.append((char)('a' + j - 1));
                    break;
                }
            }
        }
        out.println(ans);
    }

