	    factorialNumInverse[0] = factorialNumInverse[1] = 1; 

	    for (int i = 2; i <= maxN; i++) 
	        factorialNumInverse[i] = (int)((1L*naturalNumInverse[i] * factorialNumInverse[i - 1]) % p); 
