final class Solver {
	static final Solver INSTANCE = new Solver();

	void solve(Supplier<String> sc) {
		int N = Integer.parseInt(sc.get());
		for (int i = 9; i >= 1; i--) {
			if (N % i != 0) continue;
			int par = N / i;
			if (par <= 9) {
				System.out.println("Yes");
				return;
			}
		}
		System.out.println("No");
	}
}

