        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            String st = n();
            int i = 0;
            char last = st.charAt(0);
            StringBuffer str = new StringBuffer();
            str.append(last);
            for (i = 1; i < n; i++) {
                if (st.charAt(i) == last)
                    continue;
                else {
