class selection_sort{
    int[] C;
    int Nswap = 0;
    selection_sort(int[] C){
        for(int i = 0; i<C.length; i++){
            int mini = i;
            for(int j = i; j<C.length; j++){
                if(C[j]<C[mini]){
                   mini = j; 
                }
            }
            if(mini!=i){
                int tmp = C[i];
                C[i] = C[mini];
                C[mini] = tmp;
                Nswap++;
            }
        }
        this.C = C;

    }
}

