                continue;
            }
            if (c==a && p==b) {p++; break;}
            System.out.println("NO");
            return;
        }

        while (p<=n) {
            if (ni()==p) {p++; continue;}
            System.out.println("NO");
            return;
        }
        System.out.println("YES");
    }

