public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      int cnt = 0;
      int n = in.nextInt();
      for (int i = 0; i < n; i++) {
        int x = in.nextInt();
        if (primalityTest(x)) {
          cnt++;
        }
      }

      out.println(cnt);
//      End solve()
    }

    boolean primalityTest(int x) {
      if (x == 2) {
        return true;
      }

      if (x < 2 || x % 2 == 0) {
        return false;
      }

      int i = 3;
      while (Math.sqrt(x) >= i ) {
        if (x % i == 0) {
          return false;
        }

        i += 2;
      }

      return true;
    }

//    End Solution
}


