public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        int n = in.nextInt();
        int k = in.nextInt();
        double prob = 0;
        for (int i = 1; i <= n; i++) {
            if (i >= k) {
                prob++;
            } else {
                //* 1/i
                int p = (int) Math.ceil(Math.log((double) k / i) / Math.log(2));
                prob += Math.pow((1.0 / 2), p);
            }
        }
        prob *= 1.0 / n;
        out.println(prob);
        out.close();
    }

