				long operand2 = stack.pop();
				long operand1 = stack.pop();
				String operator = scanner.next();

				if (operator.equals("+")) {
					stack.push(operand1 + operand2);
				} else if (operator.equals("-")) {
					stack.push(operand1 - operand2);
				} else {
					stack.push(operand1 * operand2);
				}
			}
		}

		scanner.close();

		System.out.println(stack.pop());
	}
}

