       }

       String next() {
           while (st == null || !st.hasMoreElements()) {
               try {
                   st = new StringTokenizer(br.readLine());
               } catch (IOException e) {
                   e.printStackTrace();
               }
           }
           return st.nextToken();
       }

       int nextInt() {
           return Integer.parseInt(next());
       }

       long nextLong() {
           return Long.parseLong(next());
       }

       Double nextDouble() {
           return Double.parseDouble(next());
       }

       String nextLine() {
           String str = "";
           try {
               str = br.readLine();
           } catch (IOException e) {
               e.printStackTrace();
           }
           return str;
       }
