    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextLong();
            }
            int flag = 0;
            for (int i = n-2; i >= 0; i--) {
                if (arr[i] > arr[i+1]){
                    if (arr[i] - 1 <= arr[i+1]){
                        arr[i]--;
                    }else {
                        flag = 1;
                        break;
                    }
                }
            }
            if (flag == 1){
                out.println("No");
            }else {
                out.println("Yes");
            }
        }
    }

