        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        String s = sc.nextLine();
        Stack<Integer>sa = new Stack<>();
        int ans=0;
        for (int i =0;i<s.length();i++){
            sa.add(Integer.parseInt(s.charAt(i) + ""));
            int x = sa.pop();
            if (sa.isEmpty()){
                sa.add(x);
            }
            else {
                if (sa.peek()==1-x){
                    ans+=2;
                    sa.pop();
                }
                else {
                    sa.add(x);
                }
            }
            }
        while (sa.size()>1){
            int x=sa.pop();
            if (sa.peek()==1-x){
                sa.pop();
                ans+=2;
            }
            else break;
        }
        pw.println(ans);
        pw.flush();

    }
