	PrintWriter out;
    public Solver(InputStream in, PrintWriter out) {
    	sc = new Scanner(in);
    	this.out = out;
    }
    // ======================================================================
    public void solve() {
    	int N = ni();
    	int[] H = new int[N];
    	boolean f = true;
    	for (int i = 0; i < N; i++) {
			H[i] = ni();
			if(H[i] > 0)	f = false;
		}
    	if(f) {
    		out.println(0);
    		return;
    	}
    	int ans = 0;
    	boolean f2;
    	while(true) {
    		f = true;
    		f2 = false;
    		for (int i = 0; i < N; i++) {
    			if(H[i] > 0) {
    				if(!f2) {
    					ans++;
    					f2 = true;
    				}
        			H[i]--;
        			f = false;
    			} else {
    				f2 = false;
    			}
    		}
    		if(f)	break;
		}
    	out.println(ans);
    }
