    int prevT = 0;
    int prevX = 0;
    int prevY = 0;
    for (int[] txy : txys) {
      int t = txy[0];
      int x = txy[1];
      int y = txy[2];
      int dt = t - prevT;
      int d = Math.abs(x - prevX) + Math.abs(y - prevY);
      if (d > dt || d % 2 != dt % 2) {
        return false;
      }
      prevT = t;
      prevX = x;
      prevY = y;
    }
    return true;
  }

