	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		long N = sc.nl();
		long K = sc.nl();
		long n1 = N%K;
		long n2 = Math.abs(n1-K);
