    static class BKagamiMochi {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            ArrayList<Integer> dList = new ArrayList<>();
            while (in.hasNext()) {
                dList.add(in.nextInt());
