class Pair {
	String name;
	int time;

	Pair(String name, int time){
		this.name = name;
		this.time = time;
	}

	void overTime(int over){
		time -= over;
	}
	int getTime(){
		return time;
	}
	String getName(){
		return name;
	}
}

