  private static void execute(final IO io) throws Exception {
    final int n = io.nextInt();
    int result = 0;
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= n; j++) {
        for (int k = 1; k <= n; k++) {
          result += M.gcd(i, j, k);
        }
      }
    }
    io.println(result);
  }

  public static final class M {
    public static int gcd(int a, int b) {
      int tmp;
      while (b != 0) {
        tmp = a;
        a = b;
        b = tmp % b;
      }
      return a;
    }

    public static int gcd(final int a, final int b, final int c) {
      return gcd(gcd(a, b), c);
    }

    public static int min(final int a, final int b) {
      return a > b ? b : a;
    }

    public static int min(final int a, final int b, final int c) {
      return min(min(a, b), min(b, c));
    }
  }

  public static final class IO implements AutoCloseable {
    private final InputStream in;
    private final BufferedOutputStream out;
    private static final int BUFSIZE = 1 << 20;
    private final byte[] buf = new byte[BUFSIZE];
    private int index = 0;
    private int total = 0;
    public IO(final InputStream in, final PrintStream out) throws IOException {
      this.in = in;
      this.out = new BufferedOutputStream(out);
    }

    @Override
    public void close() throws IOException {
      in.close();
      out.close();
    }

    private int scan() throws IOException {
      if (index >= total) {
        index = 0;
        total = in.read(buf);
        if (total <= 0)
          return -1;
      }
      return buf[index++];
    }

    public String next() throws IOException {
      int c;
      for (c = scan(); c <= 32; c = scan());
      StringBuilder sb = new StringBuilder();
      for (; c > 32; c = scan())
        sb.append((char) c);
      return sb.toString();
    }

    public int nextInt() throws IOException {
      int c, val = 0;
      for (c = scan(); c <= 32; c = scan());
      boolean neg = c == '-';
      if (c == '-' || c == '+')
        c = scan();
      for (; c >= '0' && c <= '9'; c = scan())
        val = (val << 3) + (val << 1) + (c & 15);
      return neg ? -val : val;
    }

    public int[] nextInt(final int n) throws IOException {
      final int[] result = new int[n];
      for (int i = 0; i < n; i++) {
        result[i] = nextInt();
      }
      return result;
    }

    public long nextLong() throws IOException {
      int c;
      long val = 0;
      for (c = scan(); c <= 32; c = scan());
      boolean neg = c == '-';
      if (c == '-' || c == '+')
        c = scan();
      for (; c >= '0' && c <= '9'; c = scan())
        val = (val << 3) + (val << 1) + (c & 15);
      return neg ? -val : val;
    }

    public long[] nextLong(final int n) throws IOException {
      final long[] result = new long[n];
      for (int i = 0; i < n; i++) {
        result[i] = nextLong();
      }
      return result;
    }

    public void print(final Object a) throws IOException {
      out.write(a.toString().getBytes());
    }

    private static final byte[] SP = new byte[] { 0x20 };
    public void printsp(final Object a) throws IOException {
      out.write(a.toString().getBytes());
      out.write(SP);
    }

    private static final byte[] CRLF = System.lineSeparator().getBytes();
    public void println() throws IOException {
      out.write(CRLF);
    }

    public void println(final Object a) throws IOException {
      out.write(a.toString().getBytes());
      out.write(CRLF);
    }

    public void flush() throws IOException {
      out.flush();
    }
  }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        C solver = new C();
        solver.solve(1, in, out);
        out.close();
    }

    static class C {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            if (solve(in.next())) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        public boolean solve(String input) {
            String word = input + "$";

            int totalStates = 5;
            int[] statePos = new int[totalStates];
            boolean[] activeStates = new boolean[totalStates];
            activeStates[0] = true;
            boolean atLeastOnActiveState = true;
            while (atLeastOnActiveState) {

                atLeastOnActiveState = false;
                boolean[] newStates = new boolean[totalStates];
                for (int stateId = 0; stateId < totalStates - 1; stateId++) {
                    if (activeStates[stateId]) {
                        atLeastOnActiveState = true;
                        processState(stateId, statePos, newStates, word);
                    }
                }

                if (newStates[4]) {
                    return true;
                }

                activeStates = newStates;
            }

            return false;
        }

        private void processState(int stateId, int[] statePos, boolean[] newStates, String word) {
            int startIdx = statePos[stateId];
            int nextStatePos = 0;
            switch (stateId) {
                case 0:
                    if ((nextStatePos = matchString(word, "dream", startIdx)) > 0) {
                        newStates[1] = true;
                        statePos[1] = nextStatePos;
                        newStates[0] = true;
                        statePos[0] = nextStatePos;
                    } else if ((nextStatePos = matchString(word, "er", startIdx)) > 0) {
                        newStates[2] = true;
                        statePos[2] = nextStatePos;
                    } else if ((nextStatePos = matchString(word, "$", startIdx)) > 0) {
                        newStates[4] = true;
                    }
                    break;
                case 1:
                    if ((nextStatePos = matchString(word, "er", startIdx)) > 0) {
                        newStates[0] = true;
                        statePos[0] = nextStatePos;

                        newStates[2] = true;
                        statePos[2] = nextStatePos;
                    } else if ((nextStatePos = matchString(word, "$", startIdx)) > 0) {
                        newStates[4] = true;
                    }
                    break;
                case 2:
                    if ((nextStatePos = matchString(word, "as", startIdx)) > 0) {
                        newStates[3] = true;
                        statePos[3] = nextStatePos;
                    }
                    break;
                case 3:
                    if ((nextStatePos = matchString(word, "er", startIdx)) > 0) {
                        newStates[0] = true;
                        statePos[0] = nextStatePos;
                    } else if ((nextStatePos = matchString(word, "e", startIdx)) > 0) {
                        newStates[0] = true;
                        statePos[0] = nextStatePos;
                    }
                    break;
            }
        }

        private int matchString(String word, String target, int startIdx) {
            if (startIdx + target.length() > word.length()) {
                return -1;
            }

            for (int i = 0; i < target.length(); i++) {
                if (word.charAt(startIdx + i) != target.charAt(i)) {
                    return -1;
                }
            }

            return startIdx + target.length();
        }

    }
}

