public class Main {
    static boolean[] tony(int n)
    {
        boolean[] array = new boolean[n];
        for(int i = 0;i<n;i++)
        {
            array[i] = true;
        }
        array[0] = false;
        array[1] = false;
        for(int i = 2;i<= Math.sqrt((double)n);i++)
        {
            if(array[i]) {
                int j = i + i;
                while (j < n) {
                    array[j] = false;
                    j = j + i;
                }
            }
        }
        return array;
    }
