      this.writer = writer;
    }

    void run() {
      int n = sc.nextInt();
      int k = sc.nextInt();
      int[] items = sc.nextIntArray(n);
      Arrays.sort(items);
      int result = 0;
      for (int i = 0; i < k; i++) {
        result += items[i];
      }
      writer.println(result);
    }
  }

