import java.util.Scanner;

class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] p = new int[n];
		for(int i = 0; i < n; i++) p[i] = sc.nextInt();
		int cnt = 0;
		for(int i = 1; i + 1 < n; i++) {
			int max = Math.max(Math.max(p[i], p[i + 1]), p[i - 1]);
			int min = Math.min(Math.min(p[i], p[i + 1]), p[i - 1]);
			int mid = p[i] ^ p[i + 1] ^ p[i - 1] ^ max ^ min;
			if(mid == p[i]) cnt++;
		}
		System.out.println(cnt);
	}
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
    int N = in.nextInt();

    int ans = 0;
    for (int i = 1; i <= N; i += 2) {
      int count = 0;
      for (int j = 1; j <= Math.sqrt(i); j++) {
        if (i % j == 0) {
          count += 2;
        }
      }
      if (count == 8) {
        ans++;
      }
    }
    System.out.println(ans);
  }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        PrintWriter prnt = new PrintWriter(System.out);
        FastReader read = new FastReader(System.in);

        String s = read.next();
        for (int i = 0; i < s.length(); i++) {
            prnt.print("x");
        }
        prnt.close();

    }

    static void debug(Object... obj) {
        System.err.println(Arrays.deepToString(obj));
    }

    static class FastReader {
        InputStream is;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0, ptrbuf = 0;

        public FastReader(InputStream is) {
            this.is = is;
        }

        public int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        public boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) ;
            return b;
        }

        public String next() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(b))) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }


        public String nextLine() {
            int c = skip();
            StringBuilder sb = new StringBuilder();
            while (!isEndOfLine(c)) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    num = (num << 3) + (num << 1) + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public long nextLong() {
            long num = 0;
            int b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = (num << 3) + (num << 1) + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public char[] next(int n) {
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while (p < n && !(isSpaceChar(b))) {
                buf[p++] = (char) b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        public char readChar() {
            return (char) skip();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

class Main {

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		try{
			int verLineNum = Integer.parseInt(br.readLine()); //tate
			int horLineNum = Integer.parseInt(br.readLine()); //yoko
			ArrayList<Integer[]> horLineList = new ArrayList<Integer[]>();
			for(int i=0;i<horLineNum;i++){
				String[] lineStr = br.readLine().split(",");
				Integer[] lineInfo = new Integer[2];
				for(int j=0;j<lineInfo.length;j++){
					lineInfo[j] = Integer.parseInt(lineStr[j]);
				}
				horLineList.add(lineInfo);
			}

			for(int i : SortGoalLine(verLineNum, horLineList)){
				System.out.println(i);
			}
		}
		catch(Exception e){
			return;
		}
		finally{
			try {
				br.close();
			} catch (IOException e) {
				// TODO Auto-generated catch block
				return;
			}
		}
	}

	private static Integer[] SortGoalLine(int verLineNum,List<Integer[]> horizonLineList){
		Integer[] goalNum = new Integer[verLineNum];
		for(int i=0;i<goalNum.length;i++){
			goalNum[i] = i+1;
		}

		for(Integer[] i : horizonLineList){
			int temp = goalNum[i[0]-1];
			goalNum[i[0]-1] = goalNum[i[1]-1];
			goalNum[i[1]-1] = temp;
		}

		return goalNum;
	}

}

import java.io.*;
import java.util.StringTokenizer;

public class Main {

    private static FastReader in = new FastReader(System.in);
    private static PrintWriter out = new PrintWriter(System.out);

    private static final long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        String[] days = {"SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"};
        String current = in.next();

        int index = 0;
        for (int i = 0; i < days.length; i++) {
            if (days[i].equals(current)) {
                index = i;
                break;
            }
        }

        out.println(7 - index);
    }

    // https://www.geeksforgeeks.org/fast-io-in-java-in-competitive-programming/
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new
                    InputStreamReader(inputStream));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        // https://qiita.com/masakinpo/items/5f77f2a879578a85a0bb
        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

