		String[] info = sc.nextLine().split(" ");

		int n = Integer.parseInt(info[0]);
		int limit =Integer.parseInt(info[1]);
		int time = 0;

		Queue<Pair> q = new LinkedList<Pair>();
		String [] inputArrayS = new String[n];
		for (int i = 0; i < n; i += 1) {
			inputArrayS[i]  = sc.nextLine();
