			q.offer(p);
			}

			while (q.size()>0) {

					if(q.peek().value > limit) {
						Pair cp = q.remove();
						time = time + limit;


					cp.value = cp.value - limit;
					cp.key = cp.key;	
					q.add(cp);


				}else{

					time = time + q.peek().value;				
					System.out.println(q.peek().key + " " + time);
