    static class BPopularVote {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int a[] = new int[n];
            long sum = 0;
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                sum += a[i];
            }
            if (sum % 4 == 0) {
                long k = sum / (4 * m);
                int c = 0;
                for (int i = 0; i < n; i++) {
                    if (a[i] >= k) c++;
                }
                if (c >= m) out.println("Yes");
                else out.println("No");
            } else {
                long k = sum / (4 * m);
                k += 1;
                int c = 0;
                for (int i = 0; i < n; i++) {
                    if (a[i] >= k) c++;
                }
                if (c >= m) out.println("Yes");
                else out.println("No");
            }
        }

    }

