	public static int[] a = new int[4];
	public static char[] op = new char[3];
	public static void dfs( int n ) {
		if( n == 3 ) {
			int sum = a[0];
			for( int i = 0; i < 3; i++ ) {
				if( op[i] == '+'  )
					sum += a[i+1];
				else
					sum -= a[i+1];
			}
			if(sum == 7) {
				for( int i = 0; i < 4; i++ ) {
					if( i != 3 )
						System.out.print( a[i] + "" + op[i] );
					else
						System.out.println( a[i] + "=7" );
				}
				System.exit(0);
			}
		}
		else {
			op[n] = '+';
			dfs(n+1);
			op[n] = '-';
			dfs(n+1);
		}
	}

	public static void main(String args[] ) {
		Scanner sc = new Scanner(System.in);
		String s = sc.next();
		a[0] = s.charAt(0)-'0';
		a[1] = s.charAt(1)-'0';
		a[2] = s.charAt(2)-'0';
		a[3] = s.charAt(3)-'0';
		dfs(0);
		sc.close();
	}
}

import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {

        Scanner sc = new Scanner(System.in);
        String line1 = sc.nextLine();
        String line2 = sc.nextLine();

        int n = Integer.parseInt(line1);
        String[] array = line2.split(" ");

        int maxPosition = 0;
        int minPosition = 101;

        for(int i = 0; i < n; i++)
        {
            int bufPosition = Integer.parseInt(array[i]);
            if(bufPosition > maxPosition)
            {
                maxPosition = bufPosition;
            }
            if(bufPosition < minPosition)
            {
                minPosition = bufPosition;
            }
        }
        int minSum = 1000000;
        for(int p = minPosition; p <= maxPosition; p++)
        {
            int bufSum = 0;
            for(int i = 0; i < n; i++)
            {
                int bufPosition = Integer.parseInt(array[i]);
                bufSum += (bufPosition - p) * (bufPosition - p);
            }
            if(bufSum < minSum)
            {
                minSum = bufSum;
            }
        }    
        System.out.println(minSum);
    }
}

