    }
    if(i>a.length-1)
    {
      return 100000;
    }
    if(dp[i]!=-1)
    return dp[i];
    int one=10000,two=10000;
    if(i+1<=a.length-1)
    one=Math.abs(a[i]-a[i+1])+go(a,i+1);
    if(i+2<=a.length-1)
    two=Math.abs(a[i]-a[i+2])+go(a,i+2);
