    static int combination(int a,int b) {
        int count=0;
        for(int i=a;i>=1;i--)
            for(int j=i-1;j>=1;j--)
                for(int k=j-1;k>=1;k--) 
                    if(i+j+k==b)count++;
        return count;
    }
}

