								count++;		//組み合わせが見つかったためカウントアップ
							}
						}
						c = n;
					}
				}

				output += count + "\n";			//出力内容を入れる

				input = br.readLine().split("[\\s]+");	//2回目以降の入力
			}
		}catch(IOException e){
			System.out.println(e);
			return;
		}

		//出力
		System.out.print(output);

	}
}

