		long n = Long.parseLong(reader.ns());

		long min_sum = (long)1e12+5;
		for (long cur = 1; cur * cur <= n; cur ++) {
	        if (n % cur == 0) {
	            long a = cur;
	            long b = n / cur;
				min_sum = Math.min(min_sum, a + b);
	            // System.out.println(a + " " + b);
	        }
	    }

