public class Main { 

	public static void main(String[] args) {    
		FastScanner I = new FastScanner(); //Input
		OutPut O = new OutPut(); //Output
		int N = I.nextInt();
		ArrayList<String> words = new ArrayList<String>();
		for (int i = 0; i < N; i++) {
			char[] cur = I.next().toCharArray();
			Arrays.sort(cur);
			String sort = new String(cur);
			words.add(sort);
		}
		Collections.sort(words);
		long curlen = 1;
		long ans = 0;
		for (int i = 1; i < N; i++) {
			String prev = words.get(i-1);
			String cur = words.get(i);
			if (prev.equals(cur)) curlen++;
			else {
				ans+=curlen*(curlen-1)/2;
				curlen=1;
			}
		}
		ans+=curlen*(curlen-1)/2; //Last ever contiguous sub-array of anagrams
		O.pln(ans);
	}
	public static long ceil(long num, long den) {long ans = num/den; if (num%den!=0) 
	ans++; return ans;}
	public static long GCD(long a, long b) {
		if (a==0||b==0) return Math.max(a,b);
		return GCD(Math.min(a, b),Math.max(a, b)%Math.min(a, b));
	}
	public static long FastExp(long base, long exp, long mod) {
		long ans=1;
		while (exp>0) {
			if (exp%2==1) ans*=base;
			exp/=2;
			base*=base;
			base%=mod;
			ans%=mod;
		}
		return ans;
	}
	public static long ModInv(long num,long mod) {return FastExp(num,mod-2,mod);}
	public static int pop(long x) { //Returns number of bits within a number
		int cnt = 0;
		while (x>0) {
			if (x%2==1) cnt++;
			x/=2;
		}
		return cnt;
	}
