		double M,SUM;

		try {
			while((N = Integer.parseInt(br.readLine())) != 0){

				String input[] = br.readLine().split("\\s+");
				double array[] = new double[input.length];

				SUM = 0;

				for(int i = 0; i < input.length; i++){
