		solve(sc,out);

		out.flush();
	}

	public static void solve(FastScanner sc, PrintWriter out) {
		int s = sc.nextInt();

		Set<Integer> list = new HashSet<Integer>();

		list.add(s);
		int before = s;

		while(true) {	
			if(before % 2 == 0) {
				if(!list.add(before / 2)) {
					break;
				}

				before = before / 2;
			}else{
				if(!list.add(3 * before + 1)) {
					break;
				}

				before = 3 * before + 1;
			}
		}
		out.println(list.size() + 1);
	}

	public static long gcd(long a, long b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}

	public static long lcm(long a, long b) {
		return a / gcd(a, b) * b;
	}

	public static long factorial(int n) {
		long a;

		if(n > 0) {
			a = n * factorial(n - 1);
		}else{
			a = 1;
		}

		return a;
	}
}

