			m=sum/nDouble;
			sum=0;
			for(int i=0;i<n;i++){
				sum+=(s[i]-m)*(s[i]-m);
			}
			alpha=Math.sqrt(sum/n);
			System.out.printf("%.5f",alpha);
			System.out.println();
		}
	}
}

