		long tmp1 = 1;
		long tmp2 = 1;


		if (num < 3) {
			return 1;
		} else {
			long n = 0;
			for (long i = 3; i <= num; i ++) {
				n = (tmp1 + tmp2) % 1000000007;
				tmp1 = tmp2 % 1000000007;
				tmp2 = n % 1000000007;
			}
			return n;
		}

	}

