        x = x % p;  

        while (y > 0) 
        { 

            if((y & 1)==1) 
                res = (res * x) % p; 


            y = y >> 1;  
            x = (x * x) % p;  
        } 
        return res; 

    }
    static int gcd(int a, int b) 
    { 
        if (b == 0) 
            return a; 
        return gcd(b, a % b);  

    }



