	public static Boolean primenumber(int n) {
		if (n <= 3) {
			return n > 1;
		}
		else if (n%2 == 0 || n%3 == 0) {
			return false;
		}
		int i = 5;
		while (i*i <= n) {
			if (n%i == 0 || n%(i + 2) == 0) {
				return false;
			}
			i = i + 6;
		}
		return true;
	}

	public static int numberprimes(int[] P) {
		int counter = 0;
		for (int p : P) {
			if (primenumber(p)) {
				counter++;
			}
		}
		return counter;
	}

