class Solution {
	Reader reader;
	PrintWriter out;
	public Solution() {
		reader = new Reader();
		out = new PrintWriter(System.out);
		while (reader.hasNext()) {
			run_case();
		}
		out.flush();
	}

	private void run_case() {
		int n = reader.ni();
		long[] arr = new long[n];
		for (int i=0; i<n; i++) arr[i] = reader.nl();
		// Arrays.sort(arr);

		for (int i=0; i<n; i++) {
			if (arr[i] == 0) {
				out.println("0");
				return;
			}
		}

		long res = 1;
		long inf = (long)1e18;
		for (int i=0; i<n; i++) {
			long bound = inf / res;
			if (arr[i] > bound) {
				out.println("-1");
				return;
			}
			res *= arr[i];
		}

		out.println(res);
		return;
	}
}


