	public Solution () {
		reader = new Reader();
		while (reader.hasNext()) {
			run_case();
		}
	}

	private void run_case() {
		int a = reader.ni();
		int b = reader.ni();
		int c = reader.ni();

		int t = a;
		a = b;
		b = t;

		t = a;
