				int tmp = a;
				StringBuilder sb = new StringBuilder(String.valueOf(a));
				if ((i & (1 << 0)) == 0) {
					tmp += b;
					sb.append("+");
					sb.append(String.valueOf(b));
				} else {
					tmp -= b;
					sb.append("-");
					sb.append(String.valueOf(b));
				}
				if ((i & (1 << 1)) == 0) {
					tmp += c;
