import java.util.*;
import static java.lang.Math.*;

public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);

		// 入力
		int n = sc.nextInt();// N
		int a = sc.nextInt();// A
		int b = sc.nextInt();// B


		// 各桁の数の和がa以上b以下ならカウントアップ
		int Num = 0;
		for(int i = 1; i <= n; i++){
			if(a <= sumEach(i) && sumEach(i) <= b){
				Num = Num + i;
			}
		}

		// 出力
		System.out.println(Num);
	}

	// 各桁の数の和を算出
	static int sumEach(int n){

		String s = String.valueOf(n);

		int sum = 0;
		for(int i = 0; i < s.length(); i++){
			sum = sum + Integer.parseInt(s.substring(i, i + 1));
		}
		return sum;
	}

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        InputStreamScanner in = new InputStreamScanner(System.in);
        new Main().solve(in, out);
        out.flush();
    }

    private void solve(InputStreamScanner in, PrintWriter out) {
        String a = in.next();
        String b = in.next();
        BigDecimal x = new BigDecimal(a);
        BigDecimal y = new BigDecimal(b);
        out.println(x.multiply(y).setScale(0, RoundingMode.DOWN));
    }

    static class InputStreamScanner {

        private InputStream in;

        private byte[] buf = new byte[1024];
        private int len = 0;
        private int off = 0;

        InputStreamScanner(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            for (int b = skip(); !isSpace(b);){
                sb.appendCodePoint(b);
                b = read();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return (char)skip();
        }

        int skip() {
            for (int b; (b = read()) != -1;) {
                if (!isSpace(b)) {
                    return b;
                }
            }
            return -1;
        }

        private boolean isSpace(int c) {
            return c < 33 || c > 126;
        }

        private int read() {
            if (len == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (off >= len){
                off = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException(e.getMessage());
                }
                if (len <= 0) {
                    return -1;
                }
            }
            return buf[off++];
        }
    }
}

