				if (c * 2 < a) {
					z = x;
					System.out.println(c * 2 * z);
				} else {
					System.out.println(c * 2 * z + a * (x - z));
				}
			} else {
				if (c * 2 < b) {
					z = y;
					System.out.println(c * 2 * z);
				} else {
					System.out.println(c * 2 * z + b * (y - z));
				}
			}
		} else {
			System.out.println(a * x + b * y);
		}
	}
}

