import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int count = 0;
		if (n > 1) {
			count += (n * (n - 1)) / 2;
		}
		if (m > 1) {
			count += (m * (m - 1)) / 2;
		}
		System.out.println(count);
		sc.close();
	}

}

import java.util.Scanner;

public class Main {

    private static final int GOAL_BUTTON = 2;

	public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        Button[] buttons = new Button[n];

        for (int i = 0; i < n; i++) {
            Button bt = new Button(sc.nextInt());

            // ボタン1が初期で光っている
            if (i == 0) {
                bt.push();
            }

            buttons[i] = bt;
        }

        int next = buttons[0].push();
        int pushCount = 1;

        while (true) {
            if (next == GOAL_BUTTON) {

                // 押した結果光ったのが2なら終了
                System.out.println(pushCount);

                return;
            }

            if (buttons.length < next) {
                System.out.println(-1);

                return;
            }

            // 次に押すボタン
            Button targetButton = buttons[next - 1];

            // 押されたボタンを再度押すと無限に続くため2は光らせられない
            if (targetButton.isPushed()) {
                System.out.println(-1);

                return;
            } else {

                // 押されてなければ押して回数を加算
                next = targetButton.push();
                ++pushCount;
            }
        }
	}
}

class Button {

    /** 光らせるボタン */
    private int target;

    /** 光っているかどうか */
    private boolean on;

    /** 押された（光らせたか）どうか */
    private boolean pushed;

    public Button(int target) {
        this.target = target;
        on = false;
    }

    /** ボタンを押して光っている状態を反転後、光るボタンを返す */
    public int push() {
        on = !on;

        if (on) {
            pushed = true;
        }

        return target;
    }

    public int getTarget() {
        return target;
    }

    public void setTarget(int target) {
        this.target = target;
    }

    public boolean isOn() {
        return on;
    }

    public boolean isPushed() {
        return pushed;
    }
}

import java.io.*;
import java.util.*;

class Main {
    static int res;
    static int n;
    static int[] arr;

    public static void main(String args[]) throws IOException {
        Scan sc = new Scan();
        n = sc.scanInt();
        arr = new int[n];
        for(int i= 0; i < n; ++i)
            arr[i] = sc.scanInt();
        recur(0,n-1,0);
        System.out.println(res);
    }

    static void recur(int l, int r, int sofar){
        if(l < 0 || r == n || r < l)
            return;
        int min = Integer.MAX_VALUE;
        int ind_l = -1;
        int ind_r = -1;
        int prev = -1;
        for(int i = l ; i <= r; ++i){
            int curr = arr[i];
            if(curr < min){
                ind_l = i;
                ind_r = i;
                min = curr;
            }
            if(curr == prev && curr == min){
                ind_r++;
            }
            prev = curr;
        }
        res += min-sofar;

        recur(l,ind_l-1, min);
        recur(ind_r+1,r, min);
    }
}

class Scan
{
    private byte[] buf=new byte[1024];
    private int index;
    private InputStream in;
    private int total;
    public Scan()
    {
        in=System.in;
    }
    public int scan()throws IOException
    {
        if(total<0)
        throw new InputMismatchException();
        if(index>=total)
        {
            index=0;
            total=in.read(buf);
            if(total<=0)
            return -1;
        }
        return buf[index++];
    }
    public int scanInt()throws IOException
    {
        int integer=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n))
        {
            if(n>='0'&&n<='9')
            {
                integer*=10;
                integer+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        return neg*integer;
    }
    public long scanLong() throws IOException {
        long integer=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n))
        {
            if(n>='0'&&n<='9')
            {
                integer*=10;
                integer+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        return neg*integer;
    }
    public double scanDouble()throws IOException
    {
        double doub=0;
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        int neg=1;
        if(n=='-')
        {
            neg=-1;
            n=scan();
        }
        while(!isWhiteSpace(n)&&n!='.')
        {
            if(n>='0'&&n<='9')
            {
                doub*=10;
                doub+=n-'0';
                n=scan();
            }
            else throw new InputMismatchException();
        }
        if(n=='.')
        {
            n=scan();
            double temp=1;
            while(!isWhiteSpace(n))
            {
                if(n>='0'&&n<='9')
                {
                    temp/=10;
                    doub+=(n-'0')*temp;
                    n=scan();
                }
                else throw new InputMismatchException();
            }
        }
        return doub*neg;
    }
    public String scanString()throws IOException
    {
        StringBuilder sb=new StringBuilder();
        int n=scan();
        while(isWhiteSpace(n))
        n=scan();
        while(!isWhiteSpace(n))
        {
            sb.append((char)n);
            n=scan();
        }
        return sb.toString();
    }
    private boolean isWhiteSpace(int n)
    {
        if(n==' '||n=='\n'||n=='\r'||n=='\t'||n==-1)
        return true;
        return false;
    }
}

