    static void solve() {
        long n = in.nextLong();
        ArrayList<Long> div = divisors(n);
        long ans = n;
        for (int i = 0; i < div.size(); i++) {
                long temp = div.get(i) - 1 + n / div.get(i) - 1;
                ans = Math.min(ans,temp);
        }
        out.println(ans);
    }

    static ArrayList<Long> divisors(long a) {
        ArrayList<Long> div = new ArrayList<>();
        div.add(1L);
        for (long i = 2; i * i <= a; i++) {
            if (a % i == 0) {
                div.add(i);
                if (i * i != a) {
                    div.add(a / i);
                }
            }

        }
        div.add(a);
        return div;
    }

