    FastScanner sc = new FastScanner(System.in);
    String s = sc.nextLine();
    int count1 = 0;
    int count2 = 0;
    for (int i = 0; i < s.length(); i++) {
      if (((i & 1) == 0 && s.charAt(i) == '0') || ((i & 1) == 1 && s.charAt(i) == '1')) continue;
      count1++;
    }
    for (int i = 0; i < s.length(); i++) {
      if (((i & 1) == 0 && s.charAt(i) == '1') || ((i & 1) == 1 && s.charAt(i) == '0')) continue;
      count2++;
    }
    System.out.println(Math.min(count1, count2));
  }
}

