    }

    private void solve() {

        double m_deg = m * 6.0;
        double h_deg = 0.5 * (60.0 * h + m);
        double deg = 0;
        if (h_deg > m_deg) {
            deg = h_deg - m_deg;
        } else {
            deg = m_deg - h_deg;
        }

        if (deg > 180.0) {
            deg = 360 - deg;
        }

        double ans = Math.sqrt(Math.pow(a, 2.0) + Math.pow(b, 2.0) - (2.0 * a * b * Math.cos(Math.toRadians(deg))));

        System.out.println(ans);
    }
