		int beforeIndex = 0;
		for(; beforeIndex < dream.length() && beforeIndex + index < s.length(); beforeIndex++) {
			if(s.charAt(index + beforeIndex) != dream.charAt(beforeIndex)) {
				return -1;
			}
		}

		if(beforeIndex < dream.length()) {
			return -1;
		}

