			if(s.charAt(index + dream.length() + afterIndex) != eraser.charAt(afterIndex)) {
				break;
			}
		}

		if(afterIndex == 2) {
			return index + dream.length()+2;
		}else {
			return index +dream.length() ;
		}
	}

