		int count = 0;
		for(int i = 0; i < n-1; i++){
			for(int j = n-1; j >= i+1; j--){
				if(c[j]  < c[j-1]){
					int tmp = c[j];
					c[j] = c[j-1];
					c[j-1] = tmp;
					count++;
				}
			}
		}
		printArray(c);
		System.out.println(count);
		return c;
	}
	int[] insertionSort(int[]a, int n){
		for(int i = 1; i < n; i++){
			printArray(a);
			int v = a[i];
			int j = i - 1;
			while(j >= 0 && a[j] > v){
				a[j+1] = a[j];
				j--;
			}
			a[j+1] = v;
		}
		return a;
	}
