        for(int i = 0; i <= n; i++){
            for(int j = 0; j <= n-i; j++){
                int z = n-i-j;
                int zy = y-10000*i-5000*j;
                if((z == 0 && zy == 0) || (z != 0 && zy % z == 0 && zy/z == 1000)){
                    System.out.println(i + " " + j + " " + z);
                    return;
                }
            }
        }
        System.out.println("-1 -1 -1");
    }

    public static int beamSearch(long[] arr, long target){
        int left = 0;
        int right = arr.length;
        while(right-left > 1){
            int mid = (left+right)/2;
            if(arr[mid] > target){
                right = mid;
            }else{
                left = mid;
            }
        }
        return left;
    }
}

