    static class CMultiplication3 {
        public void solve(int testNumber, InputReader c, OutputWriter w) {
            long a = c.readLong();
            String ss = c.readString();
            ss = ss.replace(".", "");
            long kk = Long.parseLong(ss);
            w.printLine((a * kk) / 100);
        }

