    private void solveC() {
        Scanner sc = new Scanner(System.in);
        int A = sc.nextInt();
        int B = sc.nextInt();
        int C = sc.nextInt();
        int X = sc.nextInt();
        int Y = sc.nextInt();

        int sum = 0;
        if (C * 2 < A + B) {
            sum += C * 2 * Math.min(X, Y);
            if (Math.max(X, Y) == X) {
                if (C * 2 * (X - Y) <  (X - Y) * A) {
                    sum += C * 2 * (X - Y);
                } else {
                    sum += (X - Y) * A;
                }
            } else {
                if (C * 2 * (Y - X) < (Y - X) * B) {
                    sum += C * 2 * (Y - X);
                } else {
                    sum += (Y - X) * B;
                }
            }
        } else {
            sum += X * A + Y * B;
        }
        System.out.println(sum);
