         if (check != -1) {
            long a = n / check;
            out.println(a + check - 2);
         } else
            out.println(n - 1);
      }

      private long isPrime(long n) {
         for (int x = (int) (Math.sqrt(n)); x >= 2; x--) {
            if (n % x == 0)
               return x;
         }
         return -1;
      }

   }

   static class InputReader {
