public class Main {

  private static void answer(long[] hs) {
    if (hs.length <= 1) {
      System.out.println("Yes");
      return;
    }

    long prev = hs[0] - 1;
    for (int i = 1; i < hs.length; i++) {
      long h = hs[i];
      if (prev < h) {
        prev = h - 1;
      }

      if (prev > h) {
        System.out.println("No");
        return;
      }
    }

    System.out.println("Yes");
  }

