    static class Task {
        int N;
        int ans = 0;

        int numberOfDigits(int n) {
            return (int) Math.floor(Math.log10(n)) + 1;
        }

        void solve(InputReader in, PrintWriter out) {
            N = in.nextInt();
            for (int i = 1; i <= N; ++i) {
                if (numberOfDigits(i) % 2 == 1) ans++;
            }
            out.println(ans);
        }

    }

