				if (i == a[mId]) {
					oldAns2 = oldAns1;
					oldAns1 = 0;
					mId++;
				} else {
					ans = (oldAns1 + oldAns2) % 1000000007;
					oldAns2 = oldAns1;
					oldAns1 = ans;
				}
			} else {
				ans = (oldAns1 + oldAns2) % 1000000007;
				oldAns2 = oldAns1;
				oldAns1 = ans;
			}
		}
		System.out.println(ans);

	}
}

