			System.out.println(String.valueOf(countPrime(list)));
		} catch (Exception e) {
			e.printStackTrace();
		}

	}

	public static int countPrime(final int[] list) {
		int count = 0;

		for (int num : list) {
			if (isPrime(num)) count++;
		}
		return count;
	}

	public static boolean isPrime(final int num) {
		boolean isPrime;

		if (num < 2) {
			isPrime = false;

		} else if (num == 2) {
			isPrime = true;

		} else if (num % 2 == 0) { 
			isPrime = false;

		} else {
			isPrime = true;

			final int end = (int)Math.pow(num, 0.5);
			for (int i = 3; i <= end; i += 2) {
				if (num % i == 0) {
					isPrime = false;
					break;
				}
			}
		}
		return isPrime;
	}
}

