    static class ProblemAPaperAirplanes {
        static int KK(int k) {
            int l = 1;
            for (int i = 1; i <= k; i++) {
                l <<= 1;
            }
            return l;
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
