class Point {
    long x, y, t;
    Point(int x, int y, int t){
        this.x = x;
        this.y = y;
        this.t = t;
    }

    long dist(Point b){
        return Math.abs(b.x - this.x) + Math.abs(b.y - this.y);
    }
