		String reversed = new StringBuilder(S).reverse().toString();
		String[] values = new String[] { "remaerd", "maerd", "resare", "esare", };

		int position = 0;
		while (position < S.length()) {
			String current = reversed.substring(position, Math.min(position + 7, S.length()));

