	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		String str = fs.next();
		char beforeChar = '\0';
		for(int i = 0; i < str.length(); i++) {
			char nowChar = str.charAt(i);
			if(nowChar == beforeChar) {
				System.out.println("Bad");
