 * AtCoder Beginner Contest 095 C "Half and Half"
 *   https://abc095.contest.atcoder.jp/tasks/arc096_a/
 */
public class Main {

	public static void main(String[] args) {

		InputScanner in = new InputScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		Task task = new Task();
		task.run(in, out);

		in.close();
		out.close();
	}

	static class Task {

		public void run(InputScanner in, PrintWriter out) {

			int A = in.nextInt();
			int B = in.nextInt();
			int C = in.nextInt();
			int X = in.nextInt();
			int Y = in.nextInt();

			int ans = 0;

			if (A + B > 2 * C) {
				int ab = Math.min(X, Y);
				ans += ab * 2 * C;
				X -= ab;
				Y -= ab;
			}

			if (X > 0 && A > 2 * C) {
				ans += X * 2 * C;
			} else if (X > 0){
				ans += X * A;
			}
			if (Y > 0 && B > 2 * C) {
				ans += Y * 2 * C;
			} else if (Y > 0){
				ans += Y * B;
			}

			out.println(ans);
		}
	}

