    long MOD = 1_000_000_007;
    int inf = Integer.MAX_VALUE;

    void solve(){
        int a = ni();
        int b = ni();
        char[] c = ns().toCharArray();
        int n = c.length;
        for(int i = 0; i <n; i++){
            if(i<a || i>a){
                if(c[i]=='-'){
                    out.println("No");
