        try {
            int K = sc.nextInt();
            int A = sc.nextInt();
            int B = sc.nextInt();

            boolean possible = false;

            if(A<=K*(B/K)&&K*(B/K)<=B) possible = true;

            System.out.println(possible?"OK":"NG");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

