		int n = sc.nextInt();
		int[] h = new int[n+3];
		for(int i=1;i<=n;i++) h[i] = sc.nextInt();

		long[] dp = new long [n+3];
		Arrays.fill(dp, Long.MAX_VALUE);

		dp[1] = 0;

		for(int i=1;i<=n;i++){
			dp[i + 1] = Math.min(dp[i+1], Math.abs(h[i] - h[i+1]) + dp[i]);
			dp[i + 2] = Math.min(dp[i+2], Math.abs(h[i] - h[i+2]) + dp[i]);
		}

		System.out.println(dp[n]);
	}
