                r[i] = tmpr;
                if (R.charAt(i-1) == 'C' && R.charAt(i) == 'A') {
                    tmpr++;
                    r[i] = tmpr;
                }
            }
            int a, b;
            for (int i = 0; i < Q; i++) {
                a = sc.nextInt();
                b = sc.nextInt();
                System.out.println(tmpl - l[a-1] - r[S.length()-b]);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
