    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String a = in.readString();

            int len = a.length();
            int x = 0;
            int y = 0;

            for (int i = 0; i < len; i++) {
                if (i % 2 == 0) {
                    x += Integer.parseInt(a.substring(i, i + 1));
