		        if(-1000000 <= j && j <=1000000){
		            a[i] = j;
		        }
	        }

	        //配列の０番目に大きな数、最後に小さな数が来るように並べ変える
	        for(int i = 0; i <= a.length-1; i++){
	        	for(int j = 0; j <= a.length-2; j++){
	    		    if(a[j] < a[j+1]){
	    		    	    int w = a[j];
	    		    	    a[j] = a[j+1];
	    		    	    a[j+1] = w;
	    	    	}
	    	    }
	        }

	        //配列に格納されている整数の合計を計算
	        for(int i = 0; i < a.length; i++){
	    	    sum = sum + (long)a[i];
	        }
	    }

	    //最小値、最大値、合計を表示
