    static class edge implements Comparable<edge>{
    	int node;int cost;
    	edge(int a,int b){
    		node=a;cost=b;
    	}
		@Override
		public int compareTo(edge o) {
			if(cost!=o.cost) {
				return cost-o.cost;
			}
				return node-o.node;

		}
