			System.out.println("NO");
		}

	}

	public static int sort(int[] array){
		int count = 0;
        for(int i = 0; i < array.length; i++ ){
            int index = i;
            for(int j = i + 1; j < array.length; j++){
                if(array[j] < array[index]){
                    index = j;
                }
            }
            if(i != index){
                int tmp = array[index];
                array[index] = array[i];
                array[i] = tmp;
                count++;
            }
        }
        return count;
    }
}

