	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		int n = fs.nextInt();
		int[] x = fs.nextIntArr(n);


		int ans = 1_000_000_000;
		for(int i = 0; i <= 100; i++) {
			int total = 0;
