import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.math.BigInteger;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] a = new int[n];
      for (int i = 0; i < n; i++)
        a[i] = nextInt();
      return a;
    }

    public long[] nextLongArray(int n) {
      long[] a = new long[n];
      for (int i = 0; i < n; i++)
        a[i] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int n = sc.nextInt();
    long[] a = sc.nextLongArray(n);
    Arrays.sort(a);
    if (a[0] == 0L) {
      System.out.println(0);
      return;
    }
    BigInteger mul = BigInteger.valueOf(1L);
    BigInteger max = BigInteger.valueOf(1_000_000_000_000_000_000L);
    for (long ai: a) {
      mul = mul.multiply(BigInteger.valueOf(ai));
      if (mul.compareTo(max) > 0) {
        System.out.println(-1);
        return;
      }
    }
    System.out.println(mul.toString());
  }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			int N = sc.nextInt();
			int M = sc.nextInt();
			long[] dp = new long[N + 3];
			boolean[] broken = new boolean[N + 3];
			int mul = 1000000007;
			for (int i = 0; i < M; i++) {
				int a = sc.nextInt();
				broken[a] = true;
				if (broken[a - 1] && broken[a]) {
					System.out.println(0);
					return;
				}
			}
			dp[0] = 1;
			for (int i = 1; i <= N; i++) {
				if (i == 1) {
					if (!broken[i]) dp[i]++;
				}
				else {
					if (broken[i]) dp[i] = 0;
					else dp[i] = (dp[i - 1] + dp[i - 2]) % mul;
				}
			}
			System.out.println(dp[N]);
		}
	}

}

