					str = line;
				}
			}
		}
		catch (NumberFormatException e) {}
		catch (IOException e) {}

		return str;
	}

	private static String reverse(String str) {
		char[]	buff = str.toCharArray();
		int		nLen = str.length();
		char	c    = 0;

		for(int n1 = 0, n2 = nLen - 1; n1 < n2; n1++, n2--) {
			c        = buff[n1];
			buff[n1] = buff[n2];
			buff[n2] = c;
		}


		return String.valueOf(buff);
	}
}

