  public static final int INF = 1000000000;
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int n = sc.nextInt();
    int p[] = new int[n];
    for(int i=0; i<n; i++) p[i] = sc.nextInt();
    int cnt=0;
    for(int i=1; i<n-1; i++){
      if((p[i] > p[i-1] && p[i] < p[i+1]) || (p[i] < p[i-1] && p[i] > p[i+1]) ) cnt++;
    }
    out.println(cnt);
  }

